Procedure kocok(d: integer; kata: string);
var
  i: integer;
  c: char;
begin
  i:=1;
  repeat
    c := kata[i];
    kata[i]:= kata[i+d];
    kata[i+d] := c;
    i:=i+1;
  until (i=length(kata)-1);
  writeln(kata);
end;

